def _well_plate_definition(template_name: str) -> dict[str, Any]:
    try:
        base = WELL_PLATE_TEMPLATES[str(template_name)]
    except KeyError as error:
        raise StudioOperationError(f"Unknown well-plate template: {template_name}") from error
    definition = copy.deepcopy(base)
    rows = int(definition["rows"])
    columns = int(definition["columns"])
    pitch = float(definition["pitch_mm"])
    row_letters = [chr(ord("A") + index) for index in range(rows)]
    points: list[list[float]] = []
    labels: list[str] = []
    # Short plate dimension is local X and carries the lettered rows; the long
    # local Y dimension carries numbered columns, matching the established
    # 84 x 126 mm Workbench plate orientation.
    for row in range(rows):
        x_mm = (row - (rows - 1) / 2.0) * pitch
        for column in range(columns):
            y_mm = (column - (columns - 1) / 2.0) * pitch
            points.append([round(x_mm, 6), round(y_mm, 6), 0.0])
            labels.append(f"{row_letters[row]}{column + 1}")
    definition["sample_points_mm"] = points
    definition["well_labels"] = labels
    definition["dimensions_mm"] = list(WELL_PLATE_DIMENSIONS_MM)
    definition["sample_plane_z_mm"] = 0.0
    return definition

