# Keep this as an explicit Plotly scale rather than a named palette.  The
# Workbench sends figure JSON directly to plotly.js, and explicit stops remain
# stable across the Python and browser Plotly versions used by packaged builds.
# Every 2D/3D field map maps its own finite data minimum and maximum onto this
# complete blue-to-red range.
FIELD_HEAT_COLOURSCALE: list[list[float | str]] = [
    [0.00, "#08306b"],  # deep blue — coolest value in this map
    [0.18, "#2563eb"],
    [0.36, "#06b6d4"],
    [0.54, "#22c55e"],
    [0.72, "#facc15"],
    [0.86, "#f97316"],
    [1.00, "#dc2626"],  # red — hottest value in this map
]

# Signed vector components need direction as well as strength.  Keep zero at
# the visual midpoint and use blue/red for opposite field directions.
FIELD_SIGNED_COLOURSCALE: list[list[float | str]] = [
    [0.00, "#2563eb"],
    [0.50, "#f8fafc"],
    [1.00, "#dc2626"],
]

FIELD_MAGNITUDE_COMPONENTS = frozenset({"magnitude", "abs_x", "abs_y", "abs_z"})
FIELD_SIGNED_COMPONENTS = frozenset({"x", "y", "z"})


def field_component_is_magnitude(component: str) -> bool:
    return str(component).strip().lower() in FIELD_MAGNITUDE_COMPONENTS


def field_component_is_signed(component: str) -> bool:
    return str(component).strip().lower() in FIELD_SIGNED_COMPONENTS


def field_component_label(field: str, component: str) -> str:
    field_name = str(field).strip().upper()
    component_name = str(component).strip().lower()
    labels = {
        "magnitude": f"|{field_name}|",
        "abs_x": f"|{field_name}x|",
        "abs_y": f"|{field_name}y|",
        "abs_z": f"|{field_name}z|",
        "x": f"{field_name}x",
        "y": f"{field_name}y",
        "z": f"{field_name}z",
    }
    if component_name not in labels:
        raise StudioOperationError("The field-map component is not supported.")
    return labels[component_name]


def field_component_scalars(vectors: Any, component: str) -> np.ndarray:
    values = np.asarray(vectors, dtype=float)
    component_name = str(component).strip().lower()
    if component_name == "magnitude":
        return np.linalg.norm(values, axis=-1)
    if component_name in {"abs_x", "abs_y", "abs_z"}:
        return np.abs(values[..., "xyz".index(component_name[-1])])
    if component_name in FIELD_SIGNED_COMPONENTS:
        return values[..., "xyz".index(component_name)]
    raise StudioOperationError("The field-map component is not supported.")


def _field_opacity_for_strength(
    strength: float,
    opacity_lower: float,
    opacity_upper: float,
    lower_level: float = 0.0,
    upper_level: float = 1.0,
) -> float:
    """Map normalized field strength through the configured opacity endpoints."""
    value = max(0.0, min(1.0, float(strength)))
    low_level = max(0.0, min(1.0, float(lower_level)))
    high_level = max(0.0, min(1.0, float(upper_level)))
    low = float(opacity_lower)
    high = float(opacity_upper)
    if value <= low_level:
        return low
    if value >= high_level:
        return high
    if high_level <= low_level:
        return high
    fraction = (value - low_level) / (high_level - low_level)
    return low + (high - low) * fraction


def _field_colour_at_fraction(
    colourscale: list[list[float | str]], fraction: float
) -> tuple[int, int, int]:
    """Interpolate an RGB colour from one of the field colour scales."""
    value = max(0.0, min(1.0, float(fraction)))
    stops = [(float(stop), str(colour).lstrip("#")) for stop, colour in colourscale]
    if value <= stops[0][0]:
        colour = stops[0][1]
        return tuple(int(colour[index:index + 2], 16) for index in (0, 2, 4))
    for (left_stop, left_colour), (right_stop, right_colour) in zip(stops, stops[1:]):
        if value <= right_stop:
            span = max(1e-30, right_stop - left_stop)
            mix = (value - left_stop) / span
            left_rgb = [int(left_colour[index:index + 2], 16) for index in (0, 2, 4)]
            right_rgb = [int(right_colour[index:index + 2], 16) for index in (0, 2, 4)]
            return tuple(
                round(left + (right - left) * mix)
                for left, right in zip(left_rgb, right_rgb)
            )
    colour = stops[-1][1]
    return tuple(int(colour[index:index + 2], 16) for index in (0, 2, 4))


def field_heat_colourscale_with_opacity(
    opacity_lower: float,
    opacity_upper: float,
    lower_level: float = 0.0,
    upper_level: float = 1.0,
) -> list[list[float | str]]:
    """Return the field colour scale with alpha linked to normalized intensity."""
    positions = {float(stop) for stop, _colour in FIELD_HEAT_COLOURSCALE}
    positions.update(
        {
            max(0.0, min(1.0, float(lower_level))),
            max(0.0, min(1.0, float(upper_level))),
        }
    )
    result: list[list[float | str]] = []
    for fraction in sorted(positions):
        alpha = _field_opacity_for_strength(
            fraction, opacity_lower, opacity_upper, lower_level, upper_level
        )
        red, green, blue = _field_colour_at_fraction(FIELD_HEAT_COLOURSCALE, fraction)
        result.append([fraction, f"rgba({red},{green},{blue},{alpha:.6g})"])
    return result


def field_signed_colourscale_with_opacity(
    opacity_lower: float,
    opacity_upper: float,
    lower_level: float = 0.0,
    upper_level: float = 1.0,
) -> list[list[float | str]]:
    """Return a zero-centred diverging scale whose alpha follows |component|."""
    lower = max(0.0, min(1.0, float(lower_level)))
    upper = max(0.0, min(1.0, float(upper_level)))
    positions = {float(stop) for stop, _colour in FIELD_SIGNED_COLOURSCALE}
    positions.update(
        {
            (1.0 - upper) / 2.0,
            (1.0 - lower) / 2.0,
            (1.0 + lower) / 2.0,
            (1.0 + upper) / 2.0,
        }
    )
    result: list[list[float | str]] = []
    for fraction in sorted(positions):
        strength = abs(2.0 * fraction - 1.0)
        alpha = _field_opacity_for_strength(
            strength, opacity_lower, opacity_upper, lower_level, upper_level
        )
        red, green, blue = _field_colour_at_fraction(FIELD_SIGNED_COLOURSCALE, fraction)
        result.append([fraction, f"rgba({red},{green},{blue},{alpha:.6g})"])
    return result


def _field_opacity_scale(
    opacity_lower: float,
    opacity_upper: float,
    lower_level: float,
    upper_level: float,
    *,
    signed: bool,
) -> list[list[float]]:
    """Return Plotly opacity stops for the endpoint-clamped transfer function."""
    low = float(opacity_lower)
    high = float(opacity_upper)
    lower = max(0.0, min(1.0, float(lower_level)))
    upper = max(0.0, min(1.0, float(upper_level)))
    if not signed:
        if lower <= 0.0 and upper >= 1.0:
            return [[0.0, low], [1.0, high]]
        return [[0.0, low], [lower, low], [upper, high], [1.0, high]]
    if lower <= 0.0 and upper >= 1.0:
        return [[0.0, high], [0.5, low], [1.0, high]]
    return [
        [0.0, high],
        [(1.0 - upper) / 2.0, high],
        [(1.0 - lower) / 2.0, low],
        [(1.0 + lower) / 2.0, low],
        [(1.0 + upper) / 2.0, high],
        [1.0, high],
    ]


def awg_diameter_mm(awg: int) -> float:
    """Return nominal bare conductor diameter for American Wire Gauge."""
    return 0.127 * 92.0 ** ((36.0 - int(awg)) / 39.0)


def awg_area_mm2(awg: int) -> float:
    diameter = awg_diameter_mm(awg)
    return math.pi * (diameter / 2.0) ** 2


def awg_resistance_20_ohm_per_km(awg: int) -> float:
    """Return nominal annealed-copper DC resistance at 20 °C in ohms/km."""
    area_m2 = awg_area_mm2(awg) * 1e-6
    return COPPER_RESISTIVITY_20_OHM_M * 1000.0 / area_m2


