def default_drc_settings() -> dict[str, Any]:
    """Scene-wide physical-clearance rules stored with the workbench document."""
    return {
        "default_clearance_mm": 0.0,
        "coil_to_coil_clearance_mm": 0.0,
        # Imported triangle surfaces are adaptively refined until their
        # clearance estimate is within this distance.  This is a geometric
        # calculation tolerance, not an additional required clearance.
        "mesh_tolerance_mm": 0.1,
    }


def default_scene() -> dict[str, Any]:
    """Return a fresh copy of the packaged HM demonstration scene."""
    try:
        with DEFAULT_SCENE_RESOURCE.open("r", encoding="utf-8") as handle:
            scene = json.load(handle)
    except (OSError, json.JSONDecodeError) as error:
        raise StudioOperationError(
            f"The packaged default scene could not be loaded: {error}"
        ) from error
    if not isinstance(scene, dict):
        raise StudioOperationError("The packaged default scene is not a scene document.")
    return scene


