    def rename_snapshot(self, snapshot_id: str, name: str) -> None:
        snapshot_name = str(name).strip()
        if not snapshot_name:
            raise StudioOperationError("Snapshot name cannot be blank.")
        before = self.document()
        self._snapshot(snapshot_id)["name"] = snapshot_name
        self._commit(before)

    def delete_snapshots(self, snapshot_ids: list[str]) -> None:
        """Delete several snapshots as one undoable document operation."""
        requested = list(dict.fromkeys(str(item) for item in snapshot_ids if str(item)))
        if not requested:
            return
        existing = {str(item.get("id", "")) for item in self.snapshots}
        missing = [snapshot_id for snapshot_id in requested if snapshot_id not in existing]
        if missing:
            raise KeyError(missing[0])
        before = self.document()
        requested_set = set(requested)
        self.snapshots = [
            item for item in self.snapshots if str(item.get("id", "")) not in requested_set
        ]
        self._snapshot_current_basis_cache = {
            key: value
            for key, value in self._snapshot_current_basis_cache.items()
            if str(key[0]) not in requested_set
        }
        self._commit(before)

    def delete_snapshot(self, snapshot_id: str) -> None:
        self.delete_snapshots([snapshot_id])

    @staticmethod
    def measurement_overlay(
        result: dict[str, Any],
        *,
        max_points: int = 1400,
    ) -> dict[str, Any]:
        """Create a bounded-size 3D sample overlay from a full measurement result."""
        points = np.asarray(result["points_m"], dtype=float)
        magnitudes = np.asarray(result["magnitudes_uT"], dtype=float)
        if len(points) > max_points:
            indices = np.linspace(0, len(points) - 1, max_points, dtype=int)
            points = points[indices]
            magnitudes = magnitudes[indices]
        return {
            "kind": "measurement_samples",
            "label": result.get("label", "Measurement volume"),
            "points_m": points.tolist(),
            "magnitudes_uT": magnitudes.tolist(),
            "target_low_uT": result["stats"]["target_low_uT"],
            "target_high_uT": result["stats"]["target_high_uT"],
        }

    @staticmethod
    def measurement_cross_section_figure(result: dict[str, Any]) -> dict[str, Any]:
        """Return central XY/XZ/YZ sample cross-sections coloured by |B|."""
        points_mm = np.asarray(result.get("local_points_m", []), dtype=float).reshape(-1, 3) * 1000.0
        magnitudes = np.asarray(result.get("magnitudes_uT", []), dtype=float).reshape(-1)
        if len(points_mm) != len(magnitudes):
            raise StudioOperationError(
                "Measurement cross-sections require one field magnitude for each local sample point."
            )
        finite = np.isfinite(points_mm).all(axis=1) & np.isfinite(magnitudes)
        points_mm = points_mm[finite]
        magnitudes = magnitudes[finite]
        if not len(points_mm):
            raise StudioOperationError(
                "Measurement cross-sections require at least one finite sample point."
            )

        centre_m = result.get("local_bounds_centre_m", result.get("local_centre_m", [0.0, 0.0, 0.0]))
        centre_mm = np.asarray(centre_m, dtype=float).reshape(-1)
        if centre_mm.size != 3 or not np.isfinite(centre_mm).all():
            centre_mm = np.zeros(3, dtype=float)
        else:
            centre_mm = centre_mm * 1000.0

        cmin = float(np.min(magnitudes))
        cmax = float(np.max(magnitudes))
        if not cmax > cmin:
            pad = max(1e-9, abs(cmin) * 1e-6)
            cmin -= pad
            cmax += pad

        planes = [
            ("XY", 2, 0, 1, "x", "y", "Local X (mm)", "Local Y (mm)"),
            ("XZ", 1, 0, 2, "x2", "y2", "Local X (mm)", "Local Z (mm)"),
            ("YZ", 0, 1, 2, "x3", "y3", "Local Y (mm)", "Local Z (mm)"),
        ]
        traces: list[dict[str, Any]] = []
        for title, normal, horizontal, vertical, xref, yref, _xlabel, _ylabel in planes:
            distance = np.abs(points_mm[:, normal] - centre_mm[normal])
            closest = float(np.min(distance))
            mask = distance <= closest + 1e-8
            traces.append(
                {
                    "type": "scattergl",
                    "mode": "markers",
                    "x": points_mm[mask, horizontal].tolist(),
                    "y": points_mm[mask, vertical].tolist(),
                    "xaxis": xref,
                    "yaxis": yref,
                    "marker": {
                        "symbol": "square",
                        "size": 11,
                        "color": magnitudes[mask].tolist(),
                        "coloraxis": "coloraxis",
                    },
                    "hovertemplate": (
                        f"{title} (%{{x:.4g}}, %{{y:.4g}}) mm<br>"
                        "|B|: %{marker.color:.5g} µT<extra></extra>"
                    ),
                    "name": title,
                    "showlegend": False,
                }
            )

        layout: dict[str, Any] = {
            "template": "plotly_white",
            "margin": {"l": 55, "r": 90, "t": 58, "b": 55},
            "title": {"text": "Central local-coordinate cross sections — |B|", "x": 0.5},
            "coloraxis": {
                "colorscale": "Turbo",
                "cmin": cmin,
                "cmax": cmax,
                "colorbar": {"title": {"text": "|B| (µT)"}},
            },
            "uirevision": "measurement-cross-sections",
        }
        domains = [(0.0, 0.29), (0.355, 0.645), (0.71, 1.0)]
        for index, ((title, _normal, _h, _v, xref, _yref, xlabel, ylabel), domain) in enumerate(
            zip(planes, domains, strict=True), 1
        ):
            xkey = "xaxis" if index == 1 else f"xaxis{index}"
            ykey = "yaxis" if index == 1 else f"yaxis{index}"
            layout[xkey] = {"domain": list(domain), "title": {"text": xlabel}}
            layout[ykey] = {
                "title": {"text": ylabel},
                "scaleanchor": xref,
                "scaleratio": 1,
            }
            layout.setdefault("annotations", []).append(
                {
                    "text": title,
                    "xref": "paper",
                    "yref": "paper",
                    "x": 0.5 * (domain[0] + domain[1]),
                    "y": 1.07,
                    "showarrow": False,
                    "font": {"size": 14},
                }
            )
        return {"data": traces, "layout": layout}

